<h1><?= $admin?'مدیریت رزروها':'جلسات و درخواست‌های من' ?></h1><p class="notice">رزرو عمومی بسته است. صوت و تصویر تا تأیید زیرساخت ضبط فعال نمی‌شوند.</p>
<?php if($admin): ?><details class="card"><summary>ثبت رزرو داخلی برای عملیات</summary><p>این عملیات رزرو عمومی را باز نمی‌کند و مجوز شروع جلسه بدون شرایط مصوب نیست.</p><?= $this->start('/bookings/internal') ?><?= $this->field('user_id','شناسه داخلی کاربر') ?><?= $this->field('mentor_id','شناسه داخلی مرشد') ?><?= $this->field('starts_local','روز و ساعت شروع به وقت تهران','datetime-local') ?><input type="hidden" name="idempotency_key" value="<?= $this->val('idempotency_key',bin2hex(random_bytes(16))) ?>"><label for="booking-problem">مسئله</label><textarea id="booking-problem" name="problem" required><?= $this->val('problem') ?></textarea><button>ثبت درخواست داخلی</button></form></details><?php endif; ?>
<?php foreach($rows as $b): ?><article class="card section"><h2><?= $this->h($b['mentor_name']) ?></h2><p>وضعیت: <?= $this->status($b['state']) ?></p><time data-timestamp="<?= (int)$b['starts_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$b['starts_at'])) ?> UTC</time><p><a href="<?= $this->h($this->url('/booking?id='.$b['id'])) ?>">جزئیات و عملیات</a></p></article><?php endforeach;if(!$rows): ?><p class="card section">هنوز درخواست یا جلسه‌ای ندارید.</p><?php endif; ?>
